// UI languages a user can pick (sections 54-55). The list is generated by
// tools/i18n/translate.mjs into ./languages.json - the same manifest the web
// and mobile apps read - so a language is accepted here exactly when every
// app can show it. The backend only stores the choice and localizes default
// notification texts; API payloads, enums and webhooks stay language-neutral.
const MANIFEST = require('./languages.json');

const SUPPORTED_LANGUAGES = MANIFEST.map((l) => l.code);
const DEFAULT_LANGUAGE = 'en';

const isSupportedLanguage = (code) => typeof code === 'string' && SUPPORTED_LANGUAGES.includes(code);

module.exports = { SUPPORTED_LANGUAGES, DEFAULT_LANGUAGE, isSupportedLanguage };
